     1→/**
     2→ * Fastify Framework Adapter
     3→ * Registers routes from decorated controllers
     4→ */
     5→import Fastify, { type FastifyInstance, type FastifyRequest, type FastifyReply } from 'fastify';
     6→import cors from '@fastify/cors';
     7→import helmet from '@fastify/helmet';
     8→import 'reflect-metadata';
     9→import { container, type Constructor } from '../core/container';
    10→import { getControllerMetadata } from '../core/decorators';
    11→import { serializeError } from '../core/errors/problem-details';
    12→
    13→export interface FastifyAdapterOptions {
    14→  logger?: boolean;
    15→  prefix?: string;
    16→  adapters?: any;
    17→}
    18→
    19→/**
    20→ * Create and configure Fastify app with registered controllers
    21→ */
    22→export async function createFastifyApp(
    23→  controllers: Constructor[],
    24→  options: FastifyAdapterOptions = {}
    25→): Promise<FastifyInstance> {
    26→  const app = Fastify({
    27→    logger: options.logger ?? false,
    28→    requestIdLogLabel: 'correlationId',
    29→  });
    30→
    31→  // Enable CORS for all origins
    32→  await app.register(cors, {
    33→    origin: '*', // Allow ALL origins
    34→    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    35→    allowedHeaders: '*', // Allow ALL headers
    36→  });
    37→
    38→  // Enable security headers
    39→  await app.register(helmet, {
    40→    // Content Security Policy - disabled for JSON API
    41→    contentSecurityPolicy: false,
    42→
    43→    // HTTP Strict Transport Security - enforce HTTPS
    44→    hsts: {
    45→      maxAge: 31536000, // 1 year in seconds
    46→      includeSubDomains: true,
    47→      preload: true,
    48→    },
    49→
    50→    // X-Frame-Options - prevent clickjacking
    51→    frameguard: {
    52→      action: 'deny', // Don't allow API to be embedded in iframes
    53→    },
    54→
    55→    // X-Content-Type-Options - prevent MIME-sniffing
    56→    noSniff: true,
    57→
    58→    // Referrer-Policy - control referrer information
    59→    referrerPolicy: {
    60→      policy: 'strict-origin-when-cross-origin',
    61→    },
    62→
    63→    // X-DNS-Prefetch-Control - control DNS prefetching
    64→    dnsPrefetchControl: {
    65→      allow: false,
    66→    },
    67→
    68→    // X-Download-Options - prevent IE from executing downloads
    69→    ieNoOpen: true,
    70→
    71→    // Hide X-Powered-By header
    72→    hidePoweredBy: true,
    73→  });
    74→
    75→  // Handle empty JSON bodies (fixes SDK sending Content-Type: application/json with no body)
    76→  app.addContentTypeParser('application/json', { parseAs: 'string' }, (req, body, done) => {
    77→    if (!body || body === '') {
    78→      done(null, {});
    79→      return;
    80→    }
    81→    try {
    82→      done(null, JSON.parse(body as string));
    83→    } catch (err) {
    84→      done(err as Error, undefined);
    85→    }
    86→  });
    87→
    88→  // Inject adapters into requests
    89→  if (options.adapters) {
    90→    app.decorateRequest('adapters', null);
    91→    app.decorateRequest('tenantId', null);
    92→    app.decorateRequest('userId', null);
    93→
    94→    app.addHook('onRequest', async (request: any) => {
    95→      request.adapters = options.adapters;
    96→      // Use Skien Kommune as default tenant for demo, or null for public access
    97→      request.tenantId = request.headers['x-tenant-id'] || null;
    98→      request.userId = request.headers['x-user-id'] || null;
    99→    });
   100→  }
   101→
   102→  // Request logging
   103→  if (options.adapters?.log) {
   104→    app.addHook('onRequest', async (request) => {
   105→      options.adapters.log.info('Request received', {
   106→        method: request.method,
   107→        url: request.url,
   108→        correlationId: request.id,
   109→      });
   110→    });
   111→
   112→    app.addHook('onResponse', async (request, reply) => {
   113→      options.adapters.log.info('Request completed', {
   114→        method: request.method,
   115→        url: request.url,
   116→        statusCode: reply.statusCode,
   117→        duration: reply.elapsedTime,
   118→      });
   119→    });
   120→  }
   121→
   122→  // Global error handler (RFC 7807)
   123→  app.setErrorHandler(async (error: Error, request: FastifyRequest, reply: FastifyReply) => {
   124→    options.adapters?.log?.error('Request error', {
   125→      error: error.message,
   126→      stack: error.stack,
   127→      correlationId: request.id,
   128→    });
   129→
   130→    const problemDetails = serializeError(error, request.id);
   131→    return reply
   132→      .status(problemDetails.status)
   133→      .header('Content-Type', 'application/problem+json')
   134→      .send(problemDetails);
   135→  });
   136→
   137→  // Register controllers
   138→  for (const Controller of controllers) {
   139→    await registerController(app, Controller, options.prefix);
   140→  }
   141→
   142→  return app;
   143→}
