   145→/**
   146→ * Register a controller's routes with Fastify
   147→ */
   148→async function registerController(
   149→  app: FastifyInstance,
   150→  Controller: Constructor,
   151→  globalPrefix?: string
   152→): Promise<void> {
   153→  const metadata = getControllerMetadata(Controller);
   154→  const controllerInstance = container.resolve(Controller.name);
   155→  const prefix = joinPaths(globalPrefix, metadata.prefix);
   156→
   157→  for (const route of metadata.routes) {
   158→    const path = joinPaths(prefix, route.path);
   159→    const handler = (controllerInstance as any)[route.handler].bind(controllerInstance);
   160→
   161→    switch (route.method) {
   162→      case 'GET':
   163→        app.get(path, handler);
   164→        break;
   165→      case 'POST':
   166→        app.post(path, handler);
   167→        break;
   168→      case 'PUT':
   169→        app.put(path, handler);
   170→        break;
   171→      case 'PATCH':
   172→        app.patch(path, handler);
   173→        break;
   174→      case 'DELETE':
   175→        app.delete(path, handler);
   176→        break;
   177→    }
   178→  }
   179→}
   180→
   181→/**
   182→ * Join path segments, ensuring result starts with /
   183→ */
   184→function joinPaths(...paths: (string | undefined)[]): string {
   185→  const joined = paths
   186→    .filter(Boolean)
   187→    .map((p) => p!.replace(/^\/+|\/+$/g, ''))
   188→    .filter((p) => p.length > 0)
   189→    .join('/');
   190→  return joined ? `/${joined}` : '/';
   191→}
