     1→/**
     2→ * Health Controller - Extended
     3→ * Health checks with readiness and liveness probes
     4→ */
     5→import { Controller, Get } from '../../core/decorators';
     6→import { container } from '../../core/container';
     7→import type { FastifyRequest, FastifyReply } from 'fastify';
     8→
     9→@Controller('/health')
    10→export class HealthController {
    11→  /**
    12→   * GET /health - Basic health check
    13→   */
    14→  @Get()
    15→  async check(request: FastifyRequest, reply: FastifyReply) {
    16→    return {
    17→      status: 'ok',
    18→      timestamp: new Date().toISOString(),
    19→      version: '1.0.0',
    20→    };
    21→  }
    22→
    23→  /**
    24→   * GET /health/ready - Readiness probe
    25→   */
    26→  @Get('/ready')
    27→  async readiness(request: FastifyRequest, reply: FastifyReply) {
    28→    const db = container.resolve<any>('Database');
    29→    
    30→    try {
    31→      // Test database connection
    32→      await db.execute('SELECT 1');
    33→      
    34→      return {
    35→        status: 'ready',
    36→        checks: {
    37→          database: 'ok',
    38→        },
    39→        timestamp: new Date().toISOString(),
    40→      };
    41→    } catch (error) {
    42→      reply.code(503);
    43→      return {
    44→        status: 'not_ready',
    45→        checks: {
    46→          database: 'error',
    47→        },
    48→        timestamp: new Date().toISOString(),
    49→      };
    50→    }
    51→  }
    52→
    53→  /**
    54→   * GET /health/live - Liveness probe
    55→   */
    56→  @Get('/live')
    57→  async liveness(request: FastifyRequest, reply: FastifyReply) {
    58→    return {
    59→      status: 'alive',
    60→      uptime: process.uptime(),
    61→      memory: process.memoryUsage(),
    62→      timestamp: new Date().toISOString(),
    63→    };
    64→  }
    65→}
